# pyright: reportMissingImports=false
#!/usr/bin/env python3
"""Strict validator for production datasets generated by production helper."""

from __future__ import annotations

import argparse
import json
import sys
from pathlib import Path
from typing import Any

HELPER_DIR = Path(__file__).resolve().parent
if str(HELPER_DIR) not in sys.path:
    sys.path.insert(0, str(HELPER_DIR))

from dataset_format_utils import (
    convert_starter_json_to_pyrit_dict,
    is_starter_dataset_payload,
    load_json_payload,
)
from pyrit.models import SeedDataset
from pyrit.models.seeds.seed_objective import SeedObjective
from pyrit.models.seeds.seed_prompt import SeedPrompt


class ProductionValidationError(ValueError):
    """Raised when production validation checks fail."""


def _build_parser() -> argparse.ArgumentParser:
    """Build CLI parser.

    Returns:
        argparse.ArgumentParser: Configured parser.
    """
    parser = argparse.ArgumentParser(description="Strict validator for production dataset files.")
    parser.add_argument("input", type=Path, help="Input dataset file (.json/.yaml/.yml/.prompt).")
    parser.add_argument("--output-json", type=Path, default=None, help="Optional JSON report output path.")
    return parser


def _load_dataset(*, input_path: Path) -> SeedDataset:
    """Load a dataset from supported formats.

    Args:
        input_path (Path): Input file path.

    Returns:
        SeedDataset: Parsed dataset.
    """
    suffix = input_path.suffix.lower()
    if suffix in {".yaml", ".yml", ".prompt"}:
        return SeedDataset.from_yaml_file(str(input_path))

    if suffix == ".json":
        payload = load_json_payload(input_path=input_path)
        if is_starter_dataset_payload(payload=payload):
            payload = convert_starter_json_to_pyrit_dict(payload=payload)
        return SeedDataset.from_dict(payload)

    raise ProductionValidationError("Unsupported extension. Use .json, .yaml, .yml, or .prompt.")


def _is_multi_turn(*, dataset: SeedDataset) -> bool:
    """Infer whether dataset is multi-turn.

    Args:
        dataset (SeedDataset): Dataset object.

    Returns:
        bool: True if multi-turn patterns are found.
    """
    objective_count = sum(1 for seed in dataset.seeds if isinstance(seed, SeedObjective))
    if objective_count > 0:
        return True

    for group in dataset.seed_groups:
        prompt_count = sum(1 for seed in group.seeds if isinstance(seed, SeedPrompt))
        if prompt_count > 1:
            return True
    return False


def _validate_common_production_rules(*, dataset: SeedDataset) -> list[str]:
    """Apply strict production checks.

    Args:
        dataset (SeedDataset): Dataset object.

    Returns:
        list[str]: Validation errors.
    """
    errors: list[str] = []
    dataset_name = (dataset.dataset_name or dataset.name or "").strip()

    if not dataset_name:
        errors.append("dataset_name is missing.")
    if " " in dataset_name:
        errors.append("dataset_name contains spaces; use '-' or '_' for production datasets.")

    if len(dataset.seeds) == 0:
        errors.append("Dataset has no seeds.")

    is_multi = _is_multi_turn(dataset=dataset)

    if is_multi:
        objective_seeds = [seed for seed in dataset.seeds if isinstance(seed, SeedObjective)]
        if len(objective_seeds) != 1:
            errors.append("Multi-turn production dataset must have exactly one objective seed.")

        group_ids = {str(getattr(seed, "prompt_group_id", "") or "") for seed in dataset.seeds}
        non_empty_group_ids = {value for value in group_ids if value}
        if len(non_empty_group_ids) != 1:
            errors.append("Multi-turn production dataset must use exactly one non-empty prompt_group_id.")

        for group_index, group in enumerate(dataset.seed_groups, start=1):
            sequences = sorted(
                int(getattr(seed, "sequence", 0))
                for seed in group.seeds
                if getattr(seed, "sequence", None) is not None
            )
            if sequences and sequences != list(range(min(sequences), max(sequences) + 1)):
                errors.append(f"Group '{group_index}' has non-contiguous sequence values: {sequences}")
    else:
        objective_count = sum(1 for seed in dataset.seeds if isinstance(seed, SeedObjective))
        if objective_count > 0:
            errors.append("Single-turn production dataset should not include objective seeds.")

    return errors


def _build_report(*, dataset: SeedDataset, source_path: Path, errors: list[str]) -> dict[str, Any]:
    """Build report dictionary.

    Args:
        dataset (SeedDataset): Dataset object.
        source_path (Path): Input path.
        errors (list[str]): Validation errors.

    Returns:
        dict[str, Any]: Report payload.
    """
    return {
        "valid": len(errors) == 0,
        "source_path": str(source_path.resolve()),
        "dataset_name": dataset.dataset_name or dataset.name,
        "seed_count": len(dataset.seeds),
        "group_count": len(dataset.seed_groups),
        "is_multi_turn": _is_multi_turn(dataset=dataset),
        "errors": errors,
    }


def _print_report(*, report: dict[str, Any]) -> None:
    """Print concise production validation report.

    Args:
        report (dict[str, Any]): Report payload.
    """
    print("=== Production Dataset Validation ===")
    print(f"Dataset      : {report['dataset_name']}")
    print(f"Seeds        : {report['seed_count']}")
    print(f"Groups       : {report['group_count']}")
    print(f"Multi-turn   : {report['is_multi_turn']}")
    print(f"Valid        : {report['valid']}")

    if report["errors"]:
        print("Errors:")
        for error in report["errors"]:
            print(f"  - {error}")


def main() -> int:
    """Run CLI entrypoint.

    Returns:
        int: Exit code.
    """
    parser = _build_parser()
    args = parser.parse_args()

    input_path: Path = args.input
    output_json: Path | None = args.output_json

    if not input_path.exists():
        print(f"Input file not found: {input_path}", file=sys.stderr)
        return 2

    try:
        dataset = _load_dataset(input_path=input_path)
        errors = _validate_common_production_rules(dataset=dataset)
        report = _build_report(dataset=dataset, source_path=input_path, errors=errors)
        _print_report(report=report)

        if output_json is not None:
            output_json.write_text(json.dumps(report, indent=2), encoding="utf-8")
            print(f"JSON report written to: {output_json.resolve()}")

        return 0 if report["valid"] else 1
    except Exception as exc:
        print(f"Validation error: {exc}", file=sys.stderr)
        return 2


if __name__ == "__main__":
    raise SystemExit(main())
